10	use Filament\Forms\Components\TextInput;
11	
12	/**
13	 * Used by fields that have a repeater of related items
14	 */
15	trait HasRelatedsRepeater
16	{
17	    /**
18	     * Return the schema for the relateds repeater.
19	     */
20	    public function getRelatedsRepeater(FieldRelatedTypeEnum $type): Repeater
21	    {
22	        $repeaterSchema = [
23	            Hidden::make('type')->default($type->value),
24	            Group::make([
25	                TranslationSection::make()->columnSpan(1)->schema([
26	                    TextInput::make('label')->required()->label('Titolo'),
27	                ])
28	                    ->extraAttributes(['class' => 'mt-0 no-border'])
29	                    ->compact(),
30	            ])->columnSpanFull(),
31	        ];
32	
33	        $repeater = Repeater::make('relateds_' . $type->value)
34	            ->label($type->label())
35	            ->addActionLabel($type->labelForAddAction())
36	            ->schema($repeaterSchema)
37	            ->relationship(
38	                'relateds',
39	                modifyQueryUsing: fn ($query) => $query->where('type', $type)
40	            )
41	            ->mutateRelationshipDataBeforeCreateUsing(function (array $data) use ($type): array {
42	                $data['type'] = $type->value;
43	                return $data;
44	            })
45	            ->orderColumn('sort');
46	
47	        return $repeater;
48	    }
49	}
