248	        $rules = [];
249	
250	
251	        if ($this->hasOptions()) {
252	
253	            $allowedValues = [];
254	            if ($this->getPredefinedOptions()) {
255	                // do not use array keys to preserve order of options
256	                foreach ($this->getPredefinedOptions() as $value => $label) {
257	                    $allowedValues[] = $value;
258	                }
259	            } else {
260	                foreach ($this->model->options as $option) {
261	                    $allowedValues[] = $option->value;
262	                }
263	            }
264	
265	
266	            $rules[] = 'in:' . implode(',', $allowedValues);
267	        }
268	
269	        if ($this->model->required) {
270	            $rules[] = 'required';
271	        } else {
272	            $rules[] = 'nullable';
273	        }
274	
275	
276	        // multiple choices
277	        if ($this->hasOptions() && $this->hasMultipleChoices()) {
278	            $rules[] = 'array';
279	
280	            $maxChoices = $this->getMaxChoices();
281	
282	            // must be greter than zero to be included in the rules
283	            if ($maxChoices) {
