299	            return 1;
300	        }
301	
302	        $maxChoices = null;
303	
304	        if ($this->hasOptions() && $this->hasMultipleChoices()) {
305	
306	            // set max choices, if any, to the number of options if it is greater
307	            $maxChoices = $this->model->properties['max_choices'] ?? null;
308	            if ($maxChoices && count($this->model->options) < $maxChoices) {
309	                $maxChoices = count($this->model->options);
310	            }
311	        }
312	
313	
314	        return $maxChoices;
315	    }
