324	            $options = $this->getPredefinedOptions();
325	            $randomKey = array_rand($options);
326	            return $randomKey;
327	        }
328	
329	        if ($this->hasOptions()) {
330	
331	            if ($this->hasMultipleChoices()) {
332	                $options = $this->model->options()->pluck('value')->toArray();
333	                shuffle($options);
334	                return array_slice($options, 0, rand(1, count($options)));
335	            }
336	
337	            return $this->model->options()->inRandomOrder()->first()->value;
338	        }
