38	    /**
39	     * This is a redirect page to start a new activity
40	     * flow.
41	     * It is hit via post when the user clicks on the "Start" button
42	     * on the activity cover page.
43	     * Creates a new activity flow or restore an existing one
44	     * if user is resuming an activity.
45	     * @param int $id id of the activity
46	     */
47	    public function start(Request $request, int $id): \Illuminate\Http\RedirectResponse
48	    {
49	
50	        /**
51	         * retrieve activity (specials included)
52	         * published scope is applied by the middleware ActivitiesPreviewForAdmin, if needed
53	         */
54	        $activity =  Activity::includeSpecials()->findOrFail($id);
55	
56	        /**
57	         * Check limit of activity replay
58	         */
59	        SendYourRecipeLimit::apply($activity, $request->user());
60	
61	        /**
62	         * Create a new activity flow or restore an existing one
63	         * if user is resuming an activity.
64	         */
65	        $uuid = $this->getUuid($request->user(), $activity);
66	        $currentFlow = UserActivity::findUuid($uuid);
67	
68	
69	        /**
70	         * If activity does not have a form or a form section,
71	         * redirect to the cover page.
72	         */
73	        if (!$activity->form || !$activity->form->sections->count()) {
74	            // throw new MissingFormException($activity->id);
75	            return redirect()->to($activity->coverUrl());
76	        }
77	
78	
79	        /**
80	         * create the sections order for the activity flow, based on form settings (randomization, lock first/last)
81	         */
82	        $currentFlow->createSectionsOrder($activity->form);
83	
84	        /**
85	         * Redirect to first section
86	         */
87	        $firstSection = $currentFlow->firstSection();
88	        return redirect()->to(route('missione-form', [
89	            'userActivityUuid' => $currentFlow->uuid,
90	            'sectionId' => $firstSection->id,
91	        ]));
92	    }
