95	    /**
96	     * Show a single section of a form
97	     */
98	    public function section(Request $request): View|RedirectResponse
99	    {
100	
101	        /**
102	         * Retrieve user activity flow
103	         */
104	        $currentUserActivity = UserActivity::byUuid($request->userActivityUuid)->byUser($request->user())->firstOrFail();
