namespace App\Domain\FormResponse\Projectors;

use App\Domain\FormResponse\Events\FormAnswerGiven;
use App\FormBuilder\Models\FormResponse;
use App\FormBuilder\Services\FormResponseService;
use App\Models\User;
use Spatie\EventSourcing\EventHandlers\Projectors\Projector;

class FormResponseProjector extends Projector
{
    /**
     * Here you can specify which event should trigger which method.
     * @var array<string,string>
     */
    protected array $handlesEvents = [
        FormAnswerGiven::class => 'onAnswerGiven',
    ];


    protected FormResponseService $service;


    public function __construct(FormResponseService $service)
    {
        $this->service = $service;
    }

    /**
     * An user has just answered a question on a Form.
     * Append the answer to the response.
     * Event has already been recorded.
     */
    public function onFormAnswerGiven(FormAnswerGiven $event): void
    {
        /**
         * retrieve the response
         */
        $response = FormResponse::where('uuid', $event->aggregateRootUuid())->first();

        $this->service->appendAnswer(
            $response,
            $event->formFieldId,
            $event->answer,
        );

        $response->refresh();



    }
}

